方案A_SQL:
SELECT COUNT(*) 
FROM t_bz_config_ci_ne_root 
WHERE IS_ONLINE = 1 AND ONLINE_TIME >= DATE_SUB(NOW(), INTERVAL 1 MONTH);

方案B_SQL:
SELECT COUNT(*) 
FROM t_bz_config_ci_ne_root 
WHERE STATUS = 0 AND OFFLINE_TIME >= DATE_FORMAT(NOW() - INTERVAL 1 MONTH, '%Y-%m-01') AND OFFLINE_TIME < DATE_FORMAT(NOW(), '%Y-%m-01');
